<script setup>
import {RefreshCw} from '@/components/app/icons.js';
import {ref,watch,onBeforeUnmount} from 'vue';import {useLearning} from '@/store.js';import {api} from '@/services/api.js';
const props=defineProps({unitId:{default:''},task:Object,compact:Boolean});const store=useLearning(),data=ref(null),error=ref(''),loading=ref(false);let generation=0;
async function load(){if(store.user?.role!=='student'||!props.unitId)return;const g=++generation;data.value=null;loading.value=true;error.value='';try{const value=await api.request('/units/'+encodeURIComponent(props.unitId)+'/progress'+(props.task?.classId?'?classId='+encodeURIComponent(props.task.classId):''));if(g===generation)data.value=value}catch(e){if(g===generation)error.value=e.message}finally{if(g===generation)loading.value=false}}
watch(()=>[props.unitId,props.task?.id,store.record?.completed],load,{immediate:true});onBeforeUnmount(()=>generation++);
</script>
<template><section v-if="store.user?.role==='student'" class="unit-journey" :class="{compact}"><header><h2>{{data?.title||'单元学习'}}</h2><span v-if="data">{{data.completed}} / {{data.total}} 课已提交</span><InfoTip label="单元进度">按本人已分配任务显示；已提交表示完成流程，独立正确由原始作答与程序核验单独记录。</InfoTip><AppButton variant="ghost" size="icon-sm" aria-label="刷新单元进度" @click="load"><RefreshCw :size="16"/></AppButton></header><p v-if="loading" role="status">读取单元进度…</p><AppAlert type="error" v-if="error" class="form-error" role="alert">{{error}}<AppButton variant="outline" @click="load">重试</AppButton></AppAlert><nav v-if="data" aria-label="单元课时"><article v-for="(lesson,i) in data.lessons" :key="lesson.lessonId" :class="{'is-current':lesson.taskId===task?.id}"><span>{{String(i+1).padStart(2,'0')}}</span><div><strong>{{lesson.title}}</strong><Status v-if="lesson.taskId">{{lesson.status}}</Status></div><RouteButton v-if="lesson.target" :route="lesson.target.slice(1)" :secondary="lesson.taskId!==task?.id">{{lesson.completed?'回看':lesson.readOnly?'历史记录':'进入学习'}}</RouteButton><Status v-else>尚未分配</Status></article></nav></section></template>
